{
  "states": [
    "INIT",
    "INIT-REBOOT",
    "SELECTING",
    "REQUESTING",
    "RENEWING",
    "REBINDING",
    "BOUND"
  ],
  "transitions": [
    {
      "from": "INIT",
      "event": "DHCPDISCOVER",
      "action": "broadcasts the DHCPDISCOVER on the local hardware broadcast address to the 0xffffffff IP broadcast address and 'DHCP server' UDP port",
      "to": "SELECTING"
    },
    {
      "from": "SELECTING",
      "event": "DHCPOFFER",
      "action": "collects DHCPOFFER messages over a period of time, selects one DHCPOFFER message from the (possibly many) incoming DHCPOFFER messages",
      "to": "REQUESTING"
    },
    {
      "from": "REQUESTING",
      "event": "DHCPACK",
      "action": "records the lease expiration time as the sum of the time at which the original request was sent and the duration of the lease from the DHCPACK message",
      "to": "BOUND"
    },
    {
      "from": "REQUESTING",
      "event": "DHCPNAK",
      "action": "discards the offer",
      "to": "INIT"
    },
    {
      "from": "BOUND",
      "event": "T1 expires",
      "action": "sends DHCPREQUEST to leasing server",
      "to": "RENEWING"
    },
    {
      "from": "RENEWING",
      "event": "DHCPACK",
      "action": "records the lease expiration time as the sum of the time at which the DHCPREQUEST message was sent and the duration of the lease from the DHCPACK message",
      "to": "BOUND"
    },
    {
      "from": "RENEWING",
      "event": "T2 expires",
      "action": "broadcasts DHCPREQUEST",
      "to": "REBINDING"
    },
    {
      "from": "REBINDING",
      "event": "DHCPACK",
      "action": "records the lease expiration time as the sum of the time at which the DHCPREQUEST message was sent and the duration of the lease from the DHCPACK message",
      "to": "BOUND"
    },
    {
      "from": "REBINDING",
      "event": "DHCPNAK",
      "action": "halts network processing",
      "to": "INIT"
    },
    {
      "from": "BOUND",
      "event": "DHCPRELEASE",
      "action": "sends DHCPRELEASE message to the server",
      "to": "INIT"
    },
    {
      "from": "INIT-REBOOT",
      "event": "DHCPREQUEST",
      "action": "broadcasts the DHCPREQUEST on the local hardware broadcast address to the 'DHCP server' UDP port",
      "to": "BOUND"
    },
    {
      "from": "INIT-REBOOT",
      "event": "DHCPNAK",
      "action": "discards the offer",
      "to": "INIT"
    }
  ]
}

